import { createPlayerError } from "../../core/errors.js";

/** Returns true when the document is currently fullscreen. */
export function isFullscreen(): boolean {
  return typeof document !== "undefined" && document.fullscreenElement !== null;
}

/** Returns true when an element exposes the Fullscreen API. */
export function canFullscreen(element: HTMLElement): boolean {
  return typeof element.requestFullscreen === "function";
}

/** Requests fullscreen for an element. */
export async function requestFullscreen(element: HTMLElement): Promise<void> {
  if (!canFullscreen(element)) {
    throw createPlayerError("Fullscreen is not supported in this environment.", {
      code: "unsupported-environment",
    });
  }

  await element.requestFullscreen();
}

/** Exits fullscreen when active. */
export async function exitFullscreen(): Promise<void> {
  if (typeof document === "undefined" || typeof document.exitFullscreen !== "function") {
    throw createPlayerError("Fullscreen is not supported in this environment.", {
      code: "unsupported-environment",
    });
  }

  if (document.fullscreenElement !== null) {
    await document.exitFullscreen();
  }
}

/** Subscribes to fullscreen changes. Returns an unsubscribe function. */
export function onFullscreenChange(listener: (fullscreen: boolean) => void): () => void {
  const handler = (): void => listener(isFullscreen());
  document.addEventListener("fullscreenchange", handler);

  return () => document.removeEventListener("fullscreenchange", handler);
}
